diff --git a/lib/migrations/051-matches-item-pair-unique.ts b/lib/migrations/051-matches-item-pair-unique.ts
new file mode 100644
index 00000000..7a302261
--- /dev/null
+++ b/lib/migrations/051-matches-item-pair-unique.ts
@@ -0,0 +1,63 @@
+import type { Migration } from './types';
+
+/**
+ * Change match uniqueness from email-pair to item-pair.
+ *
+ * Before: UNIQUE(cargo_id, vessel_id, user_id) — one match per email pair.
+ *   A cargo email with two parsed items (itemIndex 0, 1) matched against the
+ *   same vessel could only persist one row; the second INSERT was silently
+ *   ignored by the old unique index.
+ *
+ * After: UNIQUE(cargo_id, vessel_id, user_id, cargo_item_index, vessel_item_index)
+ *   — one row per item-pair. Both items from a multi-cargo email can now persist
+ *   their own match rows and appear independently on the dashboard.
+ *
+ * Existing rows (item indices defaulted to 0 by migration 044) satisfy the new
+ * constraint and are kept. Only exact item-pair duplicates are removed.
+ */
+const migration051: Migration = {
+  version: 51,
+  name: '051-matches-item-pair-unique',
+  up(db) {
+    const cols = db.prepare(`PRAGMA table_info(matches)`).all() as Array<{ name: string }>;
+    const names = new Set(cols.map((c) => c.name));
+    if (!names.has('cargo_item_index')) {
+      db.exec(`ALTER TABLE matches ADD COLUMN cargo_item_index INTEGER NOT NULL DEFAULT 0`);
+    }
+    if (!names.has('vessel_item_index')) {
+      db.exec(`ALTER TABLE matches ADD COLUMN vessel_item_index INTEGER NOT NULL DEFAULT 0`);
+    }
+    // Remove duplicates per new unique tuple, keeping earliest row.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, ''), cargo_item_index, vessel_item_index
+      )
+    `);
+    // Drop the old email-pair constraint.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+    // New item-pair constraint.
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''), cargo_item_index, vessel_item_index)
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    // Remove item-pair duplicates that could not exist under the old constraint.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, vessel_id, COALESCE(user_id, '')
+      )
+    `);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
